// keeps no copy of them. Bump the submodule to pick up a brand change.
import sageTokens from "./branding/tokens/tokens.css";
import sunIcon from "./branding/icons/sun.svg";
import monitorIcon from "./branding/icons/monitor.svg";
import moonIcon from "./branding/icons/moon.svg";
